(()=>{const legacy={'scene-1':'part-6','scene-2':'part-8','scene-3':'part-7','scene-4':'part-12','scene-5':'part-12','scene-6':'part-13','scene-7':'part-3','scene-8':'part-2','scene-9':'part-10','scene-10':'part-14','scene-11':'part-15','scene-12':'part-15','sources':'resources','wic-purpose':'part-1'};const hash=location.hash.slice(1);if(location.pathname==='/'&&legacy[hash]){location.replace('/case-studies/wic/#'+legacy[hash]);return}const reduce=matchMedia('(prefers-reduced-motion:reduce)');function paint(){const p=Math.max(0,Math.min(1,scrollY/(innerHeight*.65)));document.documentElement.style.setProperty('--intro-reveal',p.toFixed(4));document.body.classList.toggle('intro-revealed',p>.12);document.body.classList.toggle('has-scrolled',scrollY>8);const header=document.querySelector('.global-header');if(document.body.classList.contains('collection-home'))header.inert=p<=.12;document.documentElement.style.setProperty('--object-shift',reduce.matches?'0px':(1-p)*60+'px')}addEventListener('scroll',paint,{passive:true});paint();document.addEventListener('click',e=>{document.querySelectorAll('.case-menu[open]').forEach(d=>{if(!d.contains(e.target))d.open=false})});document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelectorAll('.case-menu[open]').forEach(d=>{d.open=false;d.querySelector('summary').focus()})})})();
